const lockIssueForCriterionWrite = `-- name: LockIssueForCriterionWrite :one

SELECT id FROM issue
WHERE id = $1 AND workspace_id = $2
FOR NO KEY UPDATE
`

type LockIssueForCriterionWriteParams struct {
	ID          pgtype.UUID `json:"id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

// Acceptance criteria, verifications and the verification tasks of work outcomes
// (durable spec 2.3, 2.5 to 2.7, A3). outcome_verification is append-only: no
// statement here updates or deletes it (TestOutcomeAppendOnlyVerifications).
// Serializes the open-criteria count and the insert of one issue. FOR NO KEY UPDATE
// does not conflict with the FOR KEY SHARE that task enqueue takes on the issue, so
// a criterion write never waits on an enqueue.
func (q *Queries) LockIssueForCriterionWrite(ctx context.Context, arg LockIssueForCriterionWriteParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, lockIssueForCriterionWrite, arg.ID, arg.WorkspaceID)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

const setAgentTaskDurableContext = `-- name: SetAgentTaskDurableContext :execrows
UPDATE agent_task_queue
SET context = COALESCE(context, '{}'::jsonb)
    || jsonb_build_object('durable_kind', 'verification', 'outcome_id', $1::text)
WHERE id = $2
  AND status IN ('queued', 'dispatched', 'deferred')
`

type SetAgentTaskDurableContextParams struct {
	OutcomeID string      `json:"outcome_id"`
	ID        pgtype.UUID `json:"id"`
}

// Marks a verification task in its context, so the claim, the run class and the
// briefing know what it is. Only a task not yet claimed is marked.
func (q *Queries) SetAgentTaskDurableContext(ctx context.Context, arg SetAgentTaskDurableContextParams) (int64, error) {
	result, err := q.db.Exec(ctx, setAgentTaskDurableContext, arg.OutcomeID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setWorkOutcomeOverride = `-- name: SetWorkOutcomeOverride :execrows
UPDATE work_outcome
SET verdict = $1, severity = $2, fail_cause = $3,
    updated_at = now()
WHERE id = $4 AND workspace_id = $5
  AND settled_at IS NOT NULL AND settled_at >= $6::timestamptz
`

type SetWorkOutcomeOverrideParams struct {
	Verdict     string             `json:"verdict"`
	Severity    string             `json:"severity"`
	FailCause   string             `json:"fail_cause"`
	ID          pgtype.UUID        `json:"id"`
	WorkspaceID pgtype.UUID        `json:"workspace_id"`
	Since       pgtype.Timestamptz `json:"since"`
}

// A person's conclusion on a settled outcome, within the override window (spec 2.6).
func (q *Queries) SetWorkOutcomeOverride(ctx context.Context, arg SetWorkOutcomeOverrideParams) (int64, error) {
	result, err := q.db.Exec(ctx, setWorkOutcomeOverride,
		arg.Verdict,
		arg.Severity,
		arg.FailCause,
		arg.ID,
		arg.WorkspaceID,
		arg.Since,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const summarizeWorkOutcomes = `-- name: SummarizeWorkOutcomes :many
SELECT
    CASE $1::text
        WHEN 'agent' THEN COALESCE(o.agent_id::text, '')
        WHEN 'squad' THEN COALESCE(o.squad_id::text, '')
        ELSE o.work_class
    END::text AS group_key,
    count(*)::bigint AS total,
    count(*) FILTER (WHERE o.verdict = 'pass')::bigint AS passed,
    count(*) FILTER (WHERE o.verdict = 'partial')::bigint AS partial,
    count(*) FILTER (WHERE o.verdict = 'fail')::bigint AS failed,
    count(*) FILTER (WHERE o.verdict = 'unverified')::bigint AS unverified,
    count(*) FILTER (WHERE o.verdict = 'pending')::bigint AS pending
FROM work_outcome o
LEFT JOIN issue i ON i.id = o.issue_id AND i.workspace_id = o.workspace_id
WHERE o.workspace_id = $2
  AND o.created_at >= $3::timestamptz
  -- MUL-8472: private projects the caller cannot see.
  AND ($4::uuid[] IS NULL
       OR NOT (COALESCE(i.project_id, '00000000-0000-0000-0000-000000000000'::uuid) = ANY($4::uuid[])))
GROUP BY group_key
ORDER BY total DESC, group_key
`

type SummarizeWorkOutcomesParams struct {
	GroupBy          string             `json:"group_by"`
	WorkspaceID      pgtype.UUID        `json:"workspace_id"`
	Since            pgtype.Timestamptz `json:"since"`
	HiddenProjectIds []pgtype.UUID      `json:"hidden_project_ids"`
}

type SummarizeWorkOutcomesRow struct {
	GroupKey   string `json:"group_key"`
	Total      int64  `json:"total"`
	Passed     int64  `json:"passed"`
	Partial    int64  `json:"partial"`
	Failed     int64  `json:"failed"`
	Unverified int64  `json:"unverified"`
	Pending    int64  `json:"pending"`
}

// One row per group. group_by is agent, squad or work_class; the caller checks it.
func (q *Queries) SummarizeWorkOutcomes(ctx context.Context, arg SummarizeWorkOutcomesParams) ([]SummarizeWorkOutcomesRow, error) {
	rows, err := q.db.Query(ctx, summarizeWorkOutcomes,
		arg.GroupBy,
		arg.WorkspaceID,
		arg.Since,
		arg.HiddenProjectIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SummarizeWorkOutcomesRow{}
	for rows.Next() {
		var i SummarizeWorkOutcomesRow
		if err := rows.Scan(
			&i.GroupKey,
			&i.Total,
			&i.Passed,
			&i.Partial,
			&i.Failed,
			&i.Unverified,
			&i.Pending,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

